create extension if not exists pgcrypto;
create extension if not exists vector;
create type public.user_role as enum('visitor','user','editor','tool_owner','admin');
create type public.tool_status as enum('draft','published','archived');
create type public.pricing_type as enum('free','freemium','paid','free_trial','contact_sales');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role public.user_role not null default 'user',display_name text,avatar_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,parent_id uuid references public.categories(id) on delete set null,icon text,seo_title text,seo_description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.tools(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text not null,short_description text not null,website_url text not null,source_url text,logo_url text,category_id uuid not null references public.categories(id),pricing_type public.pricing_type default 'freemium',starting_price numeric(12,2),currency char(3) default 'USD',rating numeric(3,2),review_count int default 0,verified boolean default false,featured boolean default false,status public.tool_status default 'draft',health_score int,quality_score int,embedding vector(1536),last_verified_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create index tools_category_idx on public.tools(category_id);create index tools_status_idx on public.tools(status);create table public.reviews(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,rating int check(rating between 1 and 5),title text not null,body text not null,status text default 'pending',created_at timestamptz default now());
create table public.favorites(user_id uuid references auth.users(id) on delete cascade,tool_id uuid references public.tools(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,tool_id));
create table public.companies(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,website text,logo_url text,description text,verified boolean default false,created_at timestamptz default now());
create table public.features(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null);
create table public.tool_features(tool_id uuid references public.tools(id) on delete cascade,feature_id uuid references public.features(id) on delete cascade,primary key(tool_id,feature_id));
create table public.pricing_plans(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id) on delete cascade,name text not null,price numeric(12,2),currency char(3) default 'USD',billing_period text,features jsonb default '[]',is_free boolean default false,is_active boolean default true);
create table public.search_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,query text not null,intent jsonb,filters jsonb,selected_tool_id uuid references public.tools(id),created_at timestamptz default now());
create table public.affiliate_programs(id uuid primary key default gen_random_uuid(),name text not null,network text,commission_type text,commission_value numeric,cookie_days int,status text default 'active');
create table public.affiliate_links(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id) on delete cascade,program_id uuid references public.affiliate_programs(id),tracking_url text not null,status text default 'active');
create table public.affiliate_clicks(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id),affiliate_link_id uuid references public.affiliate_links(id),session_hash text,referrer text,country text,device text,created_at timestamptz default now());
create table public.tool_claims(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id) on delete cascade,claimant_id uuid references auth.users(id) on delete cascade,status text default 'pending',evidence text,created_at timestamptz default now());
create table public.tool_updates(id uuid primary key default gen_random_uuid(),tool_id uuid references public.tools(id) on delete cascade,type text not null,summary text,source_url text,created_at timestamptz default now());
create table public.admin_logs(id uuid primary key default gen_random_uuid(),admin_id uuid references auth.users(id),action text not null,entity text,entity_id uuid,old_data jsonb,new_data jsonb,created_at timestamptz default now());
create table public.articles(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,excerpt text,content text not null,status text default 'draft',author_id uuid references auth.users(id),seo_title text,seo_description text,published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.collections(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,status text default 'draft',created_at timestamptz default now());
create table public.collection_tools(collection_id uuid references public.collections(id) on delete cascade,tool_id uuid references public.tools(id) on delete cascade,position int default 0,primary key(collection_id,tool_id));
create table public.alerts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,type text not null,query text,preferences jsonb default '{}',active boolean default true,created_at timestamptz default now());
create table public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text unique not null,status text default 'active',created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id) values(new.id);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.tools enable row level security;alter table public.reviews enable row level security;alter table public.favorites enable row level security;alter table public.articles enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role in('admin','editor'))$$;
create policy "published tools" on public.tools for select using(status='published');create policy "admin tools" on public.tools for all using(public.is_admin()) with check(public.is_admin());
create policy "categories public" on public.categories for select using(true);create policy "categories admin" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "own profile" on public.profiles for select using(id=auth.uid());create policy "admin profiles" on public.profiles for select using(public.is_admin());
create policy "approved reviews" on public.reviews for select using(status='approved');create policy "create reviews" on public.reviews for insert with check(auth.uid()=user_id);
create policy "own favorites" on public.favorites for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "published articles" on public.articles for select using(status='published');create policy "admin articles" on public.articles for all using(public.is_admin()) with check(public.is_admin());
insert into public.categories(name,slug,description) values('Video','video','AI video tools'),('Image','image','AI image tools'),('Writing','writing','AI writing tools'),('Coding','coding','AI coding tools'),('Voice','voice','AI voice tools'),('Marketing','marketing','AI marketing tools') on conflict(slug) do nothing;
